def write_back_history(apps, schema_editor):
    """Jobs that ran before the log existed get their history from what the
    records already say: when visits opened, were scanned, photographed,
    started, completed and reviewed; what was asked for, decided, issued and
    settled. Who assigned a visit was never recorded, so those lines carry
    no name."""
    Schedule = apps.get_model("maintenance", "MaintenanceSchedule")
    Activity = apps.get_model("maintenance", "MaintenanceActivity")
    Visit = apps.get_model("maintenance", "MaintenanceVisit")
    Photo = apps.get_model("maintenance", "MaintenanceVisitPhoto")
    Part = apps.get_model("maintenance", "MaintenancePartRequest")

    def who(u):
        return (f"{u.first_name} {u.last_name}".strip() or u.username) if u else ""

    rows = []

    def add(job, at, action, text, actor=None, visit=None):
        if at is not None:
            rows.append(Activity(schedule=job, visit=visit, action=action, text=text[:500], actor=actor, at=at))

    kinds = {"before": "Before", "after": "After", "other": "Other"}
    for job in Schedule.objects.select_related("device", "ticket").iterator():
        if Activity.objects.filter(schedule=job).exists():
            continue
        corrective = job.maintenance_type == "corrective"
        word = "Visit" if corrective else "Round"
        ticket = job.ticket if job.ticket_id else None
        add(job, job.created_at, "opened",
            f"Job opened from ticket {ticket.ticket_number}" if ticket is not None
            else f"{'Corrective' if corrective else 'Preventive'} job created"
            + (f" for {job.device.asset_code}" if job.device_id and ticket is None else ""),
            actor=getattr(ticket, "reported_by", None) if ticket is not None else None)
        for v in Visit.objects.filter(schedule=job).select_related("assigned_to", "asset_verified_by", "reviewed_by"):
            add(job, v.created_at, "assigned",
                f"{word} {v.sequence} opened" + (f" for {who(v.assigned_to)}" if v.assigned_to_id else "")
                + (f", due {v.due_date:%d %b %Y}" if v.due_date else ""), visit=v)
            if v.asset_verified_at:
                add(job, v.asset_verified_at, "asset_scanned",
                    f"Asset {job.device.asset_code} scanned on site" if job.device_id else "Asset scanned on site",
                    actor=v.asset_verified_by, visit=v)
            for ph in Photo.objects.filter(visit=v).select_related("taken_by"):
                add(job, ph.taken_at or ph.created_at, "photo", f"{kinds.get(ph.kind, 'Other')} photo added",
                    actor=ph.taken_by, visit=v)
            if v.started_at and v.status != "planned":
                add(job, v.started_at, "started", f"{word} {v.sequence} started on site", actor=v.assigned_to, visit=v)
            if v.completed_at:
                verdict = "" if not corrective else (" - fault fixed" if v.resolved else " - fault not fixed")
                add(job, v.completed_at, "completed", f"{word} {v.sequence} completed and sent for review{verdict}",
                    actor=v.assigned_to, visit=v)
            if v.reviewed_at and v.review_decision:
                if v.review_decision == "accepted":
                    add(job, v.reviewed_at, "accepted", f"{word} {v.sequence} accepted", actor=v.reviewed_by, visit=v)
                else:
                    add(job, v.reviewed_at, "sent_back",
                        f"{word} {v.sequence} sent back" + (f": {v.review_reason}" if v.review_reason else ""),
                        actor=v.reviewed_by, visit=v)
        for line in Part.objects.filter(schedule=job).select_related(
            "requested_by", "decided_by", "item__material_type", "unit_type", "issuance_request__issued_by", "visit",
        ):
            what = line.name or (
                (line.item.material_type.name if line.item_id and line.item.material_type_id else "")
                or (line.unit_type.name if line.unit_type_id else "") or "a part"
            )
            add(job, line.created_at, "part_requested", f"Requested {line.quantity_requested} of {what}",
                actor=line.requested_by, visit=line.visit)
            if line.decided_at:
                if line.status == "rejected":
                    add(job, line.decided_at, "part_rejected", f"Request for {what} rejected", actor=line.decided_by, visit=line.visit)
                elif line.status == "cancelled":
                    add(job, line.decided_at, "part_withdrawn", f"Request for {what} withdrawn", actor=line.decided_by, visit=line.visit)
                elif line.status == "approved":
                    add(job, line.decided_at, "part_approved", f"Request for {what} approved: {line.quantity_approved}",
                        actor=line.decided_by, visit=line.visit)
            issue = line.issuance_request if line.issuance_request_id else None
            if issue is not None and issue.quantity_issued and issue.last_issued_at:
                add(job, issue.last_issued_at, "part_issued",
                    f"Store issued {issue.quantity_issued} of {what} ({issue.request_number})",
                    actor=issue.issued_by, visit=line.visit)
            if line.quantity_used is not None:
                add(job, line.updated_at, "parts_settled",
                    f"{what}: {line.quantity_used} used"
                    + (f", {line.quantity_returned} back to the store on {line.return_reference}" if line.quantity_returned else ""),
                    visit=line.visit)
        if job.status == "cancelled":
            add(job, job.updated_at, "cancelled", "Job cancelled")
        if len(rows) > 500:
            Activity.objects.bulk_create(rows)
            rows.clear()
    Activity.objects.bulk_create(rows)



